def mean_valid_mark(marks):
    valid_marks = []
    for mark in marks:
        if 0 <= mark <= 100:
            valid_marks.append(mark)

    if len(valid_marks) == 0:
        return None
    return sum(valid_marks) / len(valid_marks)

class BankAccount:
    def __init__(self, owner, opening_balance=0.0):
        if opening_balance < 0:
            raise ValueError("opening balance cannot be negative")
        self._owner = owner
        self._balance = opening_balance

    def get_balance(self):
        return self._balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("deposit must be positive")
        self._balance += amount

account = BankAccount("Alex", 50.0)
account.deposit(25.0)
print(account.get_balance())  # 75.0

class Notification:
    def send(self, message):
        raise NotImplementedError

class EmailNotification(Notification):
    def send(self, message):
        return f"Email: {message}"

class TextNotification(Notification):
    def send(self, message):
        return f"SMS: {message}"

def send_alert(channel, message):
    print(channel.send(message))

send_alert(EmailNotification(), "Exam at 09:00")
send_alert(TextNotification(), "Exam at 09:00")

class Student:
    def __init__(self, name):
        self.name = name

class Course:
    def __init__(self, title):
        self.title = title
        self.students = []

    def enrol(self, student):
        self.students.append(student)

course = Course("Computer Science")
course.enrol(Student("Mina"))
